ALTER TABLE public.assets ADD COLUMN asset_number text, ADD COLUMN room_count integer NOT NULL DEFAULT 10;
CREATE UNIQUE INDEX assets_number_unique ON public.assets(lower(asset_number)) WHERE asset_number IS NOT NULL;
ALTER TABLE public.assets ADD CONSTRAINT assets_room_count_valid CHECK(room_count BETWEEN 1 AND 200);
ALTER TABLE public.event_bunks ADD COLUMN asset_id uuid REFERENCES public.assets(id), ADD COLUMN placement_id uuid REFERENCES public.event_asset_assignments(id) ON DELETE CASCADE, ADD COLUMN room_number integer, ADD COLUMN retired boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX event_trailer_room_unique ON public.event_bunks(placement_id,room_number) WHERE placement_id IS NOT NULL;
COMMENT ON COLUMN public.event_bunks.section IS 'Legacy grouping only; new rooms belong to asset_id and placement_id. Existing unlinked rooms retain history.';
CREATE FUNCTION public.asset_number_suggestion(p_year integer,p_letter text DEFAULT 'B') RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE prefix text; sequence integer; BEGIN IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required'; END IF; IF p_year<1900 OR p_year>2099 OR p_letter !~ '^[A-Za-z]$' THEN RAISE EXCEPTION 'Choose a purchase year and one letter'; END IF; prefix:=right(p_year::text,2)||upper(p_letter); SELECT coalesce(max(substring(asset_number from 4)::integer),0)+1 INTO sequence FROM public.assets WHERE upper(asset_number) ~ ('^'||prefix||'[0-9]+$'); RETURN prefix||CASE WHEN sequence<10 THEN '0' ELSE '' END||sequence::text; END $$;
REVOKE ALL ON FUNCTION public.asset_number_suggestion(integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.asset_number_suggestion(integer,text) TO authenticated;
CREATE FUNCTION public.sync_trailer_rooms(p_placement uuid) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE placement public.event_asset_assignments; trailer public.assets; BEGIN SELECT * INTO placement FROM public.event_asset_assignments WHERE id=p_placement; SELECT * INTO trailer FROM public.assets WHERE id=placement.asset_id FOR UPDATE; IF trailer.type<>'bunk_trailer' OR placement.end_at IS NOT NULL THEN RETURN; END IF; INSERT INTO public.event_bunks(event_location_id,asset_id,placement_id,room_number,code) SELECT placement.event_location_id,trailer.id,placement.id,n,coalesce(trailer.asset_number,trailer.label)||'-'||CASE WHEN n<10 THEN '0' ELSE '' END||n::text FROM generate_series(1,trailer.room_count) n ON CONFLICT(placement_id,room_number) WHERE placement_id IS NOT NULL DO NOTHING; UPDATE public.event_bunks SET code=coalesce(trailer.asset_number,trailer.label)||'-'||CASE WHEN room_number<10 THEN '0' ELSE '' END||room_number::text,retired=room_number>trailer.room_count WHERE placement_id=placement.id; END $$;
REVOKE ALL ON FUNCTION public.sync_trailer_rooms(uuid) FROM PUBLIC,anon;
CREATE FUNCTION public.trailer_asset_configuration() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE placement record; BEGIN IF TG_WHEN='BEFORE' THEN NEW.asset_number:=nullif(upper(trim(NEW.asset_number)),''); IF TG_OP='UPDATE' THEN IF OLD.type='bunk_trailer' AND NEW.type<>'bunk_trailer' AND EXISTS(SELECT 1 FROM public.event_asset_assignments WHERE asset_id=OLD.id AND end_at IS NULL) THEN RAISE EXCEPTION 'Unassign the trailer before changing its type'; END IF; IF EXISTS(SELECT 1 FROM public.event_bunks b JOIN public.event_bunk_assignments a ON a.bunk_id=b.id WHERE b.asset_id=OLD.id AND a.checked_out_at IS NULL AND (b.room_number>NEW.room_count OR NEW.deleted_at IS NOT NULL OR NEW.type<>'bunk_trailer')) THEN RAISE EXCEPTION 'Check occupants out before removing rooms or retiring the trailer'; END IF; END IF; ELSE FOR placement IN SELECT id FROM public.event_asset_assignments WHERE asset_id=NEW.id AND end_at IS NULL LOOP PERFORM public.sync_trailer_rooms(placement.id); END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER trailer_asset_validate BEFORE INSERT OR UPDATE ON public.assets FOR EACH ROW EXECUTE FUNCTION public.trailer_asset_configuration(); CREATE TRIGGER trailer_asset_sync AFTER INSERT OR UPDATE OF asset_number,room_count,type,label ON public.assets FOR EACH ROW EXECUTE FUNCTION public.trailer_asset_configuration();
CREATE FUNCTION public.trailer_placement_rooms() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE asset_key uuid; BEGIN asset_key:=CASE WHEN TG_OP='DELETE' THEN OLD.asset_id ELSE NEW.asset_id END; PERFORM 1 FROM public.assets WHERE id=asset_key FOR UPDATE; IF TG_WHEN='BEFORE' THEN IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND NEW.end_at IS DISTINCT FROM OLD.end_at) THEN IF EXISTS(SELECT 1 FROM public.event_bunks b JOIN public.event_bunk_assignments a ON a.bunk_id=b.id WHERE b.placement_id=OLD.id AND (a.checked_out_at IS NULL OR (TG_OP<>'DELETE' AND a.checked_out_at>NEW.end_at))) THEN RAISE EXCEPTION 'Check all trailer occupants out before moving or unassigning; departure must follow their check-outs'; END IF; END IF; ELSE PERFORM public.sync_trailer_rooms(NEW.id); END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER trailer_placement_guard BEFORE UPDATE OR DELETE ON public.event_asset_assignments FOR EACH ROW EXECUTE FUNCTION public.trailer_placement_rooms(); CREATE TRIGGER trailer_placement_sync AFTER INSERT ON public.event_asset_assignments FOR EACH ROW EXECUTE FUNCTION public.trailer_placement_rooms();
CREATE FUNCTION public.trailer_room_checkin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE room public.event_bunks; placement public.event_asset_assignments; BEGIN SELECT * INTO room FROM public.event_bunks WHERE id=NEW.bunk_id; IF room.asset_id IS NULL THEN RETURN NEW; END IF; PERFORM 1 FROM public.assets WHERE id=room.asset_id FOR UPDATE; SELECT * INTO placement FROM public.event_asset_assignments WHERE id=room.placement_id; IF NEW.event_location_id<>placement.event_location_id OR NEW.checked_in_at<placement.start_at OR (placement.end_at IS NOT NULL AND (NEW.checked_out_at IS NULL OR NEW.checked_out_at>placement.end_at)) THEN RAISE EXCEPTION 'Room stay must fall within the trailer location placement'; END IF; IF TG_OP='INSERT' AND (room.retired OR placement.end_at IS NOT NULL) THEN RAISE EXCEPTION 'Room is no longer available at this location'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trailer_room_checkin BEFORE INSERT OR UPDATE ON public.event_bunk_assignments FOR EACH ROW EXECUTE FUNCTION public.trailer_room_checkin();
CREATE OR REPLACE FUNCTION public.asset_catalog() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE money boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; money := public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'); RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('id',a.id,'type',a.type,'label',a.label,'asset_number',a.asset_number,'room_count',a.room_count,'description',a.description,'address',a.address,'gate_code',a.gate_code,'access_instructions',a.access_instructions,'operating_hours',a.operating_hours,'instructions',a.instructions,'serial_number',a.serial_number,'status',a.status,'ownership',a.ownership,'vendor_id',a.vendor_id,'vendor_name',v.name,'created_at',a.created_at,'updated_at',a.updated_at,'deleted_at',a.deleted_at) || CASE WHEN money THEN jsonb_build_object('default_day_rate',a.default_day_rate,'unit_cost',a.unit_cost,'rental_rate',a.rental_rate,'rental_period',a.rental_period,'notes',a.notes,'metadata',a.metadata) ELSE '{}'::jsonb END ORDER BY a.label) FROM public.assets a LEFT JOIN public.vendors v ON v.id=a.vendor_id WHERE a.deleted_at IS NULL),'[]'::jsonb); END $$;